class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def reverseList(self, head):
        values = []
        cur = head
        while cur:
            values.append(cur.val)
            cur = cur.next

        cur = head
        for value in reversed(values):
            cur.val = value  # Reuse nodes, but reverse the values.
            cur = cur.next
        return head

