class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def reverseList(self, head):
        prev = None
        cur = head
        while cur:
            nxt = cur.next      # Save the rest before breaking the link.
            cur.next = prev
            prev = cur
            cur = nxt
        return prev

